<script setup>
import { onMounted, reactive, ref } from "vue";
import { ArrowUpRight, Check, KeyRound, Link2, LoaderCircle, RefreshCw, UserRound } from "lucide-vue-next";
import { api } from "../api/client";
const students = ref([]); const applications = ref([]); const admissionNumber = ref(""); const message = ref(""); const loading = ref(true); const savingId = ref(null); const passwords = reactive({});
const statusLabel = { pending: "审核中", approved: "已通过", rejected: "已拒绝" };
function name(student) { return [student?.first_name, student?.second_name, student?.surname].filter(Boolean).join(" "); }
async function load() { loading.value = true; try { const [parent, links] = await Promise.all([api.get(`/parents/${localStorage.getItem("parent")}`, "parent"), api.get("/parent_students", "parent")]); students.value = parent?.students || []; applications.value = Array.isArray(links) ? links : []; localStorage.setItem("parent_data", JSON.stringify(parent)); } catch (cause) { message.value = cause.message || "孩子信息加载失败"; } finally { loading.value = false; } }
async function bindChild() { if (!admissionNumber.value) return; try { await api.post("/parent_students", { admission_number: admissionNumber.value }, "parent"); admissionNumber.value = ""; message.value = "绑定申请已提交，等待管理员审批。"; await load(); } catch (cause) { message.value = cause.message || "未找到该学号对应的孩子"; } }
async function updatePassword(id) { const value = (passwords[id] || "").trim(); if (!value) return; savingId.value = id; try { await api.patch(`/parent/children/${id}/password`, { password: value }, "parent"); passwords[id] = ""; message.value = "儿童端密码已更新。"; } catch (cause) { message.value = cause.message || "密码更新失败"; } finally { savingId.value = null; } }
onMounted(load);
</script>
<template><div><div class="page-heading"><div><span class="mono-label">FAMILY / CHILDREN</span><h1>我的孩子</h1><p>提交学号后需要管理员审批，通过后才能查看孩子详情。</p></div><button class="button button-light" @click="load"><RefreshCw :size="15" />刷新</button></div><div v-if="message" class="notice" style="margin-bottom:14px">{{ message }}</div><section class="surface surface-pad"><div class="surface-title"><h2><Link2 :size="16" style="vertical-align:-3px; margin-right:6px" />绑定新的孩子</h2><span>需要管理员审批</span></div><form style="display:flex; flex-wrap:wrap; gap:9px" @submit.prevent="bindChild"><input v-model="admissionNumber" class="filter-input" type="text" placeholder="请输入孩子学号" required /><button class="button button-primary" type="submit"><Link2 :size="15" />提交绑定申请</button></form></section><div class="data-grid" style="margin-top:18px"><section class="surface"><div class="surface-title" style="padding:18px 18px 0"><h2>审批状态</h2><span>{{ applications.length }} 条申请</span></div><div v-if="loading" class="empty-state"><LoaderCircle class="spin" :size="26" /></div><div v-else-if="!applications.length" class="empty-state"><strong>暂无绑定申请</strong><span>提交学号后，审批状态会显示在这里。</span></div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>孩子</th><th>学号</th><th>状态</th></tr></thead><tbody><tr v-for="item in applications" :key="item.id"><td>{{ item.student_name }}</td><td>{{ item.admission_number }}</td><td><span class="status" :class="item.status === 'approved' ? 'ok' : item.status === 'rejected' ? 'danger' : 'warn'">{{ statusLabel[item.status] || item.status }}</span></td></tr></tbody></table></div></section><section class="surface"><div class="surface-title" style="padding:18px 18px 0"><h2>已通过的孩子</h2><span>{{ students.length }} 位孩子</span></div><div v-if="loading" class="empty-state"><LoaderCircle class="spin" :size="26" /></div><div v-else-if="!students.length" class="empty-state"><UserRound :size="28" style="margin-bottom:10px; color:#75cfc3" /><strong>还没有已通过的孩子</strong><span>通过审批后，孩子会出现在这里。</span></div><div v-else style="display:grid; gap:10px; padding:0 18px 18px"><article v-for="student in students" :key="student.id" style="padding:15px; border:1px solid var(--light-line); border-radius:10px; background:#fff"><div style="display:flex; align-items:flex-start; justify-content:space-between; gap:10px"><div><span class="mono-label">CHILD / {{ student.admission_number }}</span><h3 style="margin:7px 0 4px; color:#1a4b61; font-size:16px">{{ name(student) }}</h3><small style="color:#748c97">{{ student.classroom?.name || '班级信息同步中' }}</small></div><div class="row-actions"><RouterLink class="button button-primary" :to="`/parent_dashboard/my_kids/${student.id}/growth`">成长记录 <ArrowUpRight :size="14" /></RouterLink><RouterLink class="row-action" :to="`/parent_dashboard/my_kids/${student.id}`">档案</RouterLink></div></div><div style="display:flex; gap:8px; margin-top:14px"><input v-model="passwords[student.id]" class="filter-input" type="password" placeholder="设置儿童端新密码" /><button class="button button-light" type="button" :disabled="savingId === student.id" @click="updatePassword(student.id)"><KeyRound :size="14" />{{ savingId === student.id ? '保存中' : '设置' }}</button></div></article></div></section></div></div></template>
<style scoped>.spin { animation: spin 1s linear infinite; } @keyframes spin { to { transform:rotate(360deg); } }</style>
